	/** 
	 * jumpstart the process by instantiating2 Candidate
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		candidateId = CandidateService.getCandidateInstance()
		.createCandidate( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CandidateService.getCandidateInstance()
				.createCandidate( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.candidateSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Candidate : " + successValue.getCandidateId());
							  if (successValue.getCandidateId().equals(candidateId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCandidateList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Candidate test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on candidate consumed")
					);
			subscriber.candidateSubscribe( candidateId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Candidate : " + successValue.getCandidateId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCandidateList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on candidate for candidateId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Candidate. 
	 */
	protected Candidate read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Candidate" );

		Candidate entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Candidate with primary key" );
		msg.append( candidateId );
		
		CandidateFetchOneSummary fetchOneSummary = new CandidateFetchOneSummary( candidateId );

		try {
			entity = CandidateService.getCandidateInstance().getCandidate( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Candidate " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Candidate.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Candidate." );

		StringBuilder msg = new StringBuilder( "Failed to update a Candidate : " );        
		Candidate entity = read();
		UpdateCandidateCommand command = generateUpdateCommand();
		command.setCandidateId(entity.getCandidateId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Candidate." );

			// for use later on...
			candidateId = entity.getCandidateId();

			CandidateService proxy = CandidateService.getCandidateInstance();  

			proxy.updateCandidate( command ).get();

			LOGGER.info( "-- Successfully saved Candidate - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + candidateId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Candidate.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Candidate." );

		Candidate entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Candidate with id " + candidateId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Candidate with id " + candidateId );

			throw e;
		}

		try{
			CandidateService.getCandidateInstance().delete( new DeleteCandidateCommand( entity.getCandidateId() ) ).get();
			LOGGER.info( "-- Successfully deleted Candidate with id " + candidateId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Candidate with id " + candidateId );

			throw e;
		}
	}

	/**
	 * get all Candidates.
	 */
	protected List<Candidate> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Candidates:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Candidate : " );        
		List<Candidate> collection  = new ArrayList<>();

		try {
			// call the static get method on the CandidateService
			collection = CandidateService.getCandidateInstance().getAllCandidate();
			assertNotNull( collection, "An Empty collection of Candidate was incorrectly returned.");
			
			// Now print out the values
			Candidate entity = null;            
			Iterator<Candidate> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCandidateId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

